-- 022: Noticias del Observatorio de Asuntos de Género (ICBF Regional Boyacá + OGDH UPTC). Idempotente por slug.

SET NAMES utf8mb4;

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'ICBF: «Una Hora por la Prevención» llegó a 225 instituciones educativas y 114 municipios de Boyacá', 'icbf-una-hora-por-la-prevencion', 'La estrategia “Una Hora por la Prevención” se desarrolló en el departamento con el propósito de fortalecer las capacidades de protección y prevención de violencias en niños, niñas y adolescentes, población reconocida como sujetos de especial protección constitucional. La…', '<p>La estrategia “Una Hora por la Prevención” se desarrolló en el departamento con el propósito de fortalecer las capacidades de protección y prevención de violencias en niños, niñas y adolescentes, población reconocida como sujetos de especial protección constitucional. La actividad consistió en la realización de cuatro sesiones de talleres de prevención por ciclo vital, en los cuales se socializaron herramientas para la prevención de violencias, la activación de rutas de atención y el reconocimiento de entornos protectores. En el marco de la estrategia BOYACTUAR, el componente dirigido a niños, niñas y adolescentes se enfocó en el reconocimiento de la escuela como escenario de construcción de entornos seguros y protectores, consolidándose como un espacio clave para la promoción de derechos y la generación de confianza en las instituciones.</p><p>La estrategia alcanzó una amplia cobertura territorial, llegando a 225 instituciones educativas del departamento y 1175 unidades de atención del ICBF en 114 municipios, lo que permitió impactar de manera significativa a miles de niños, niñas y adolescentes.</p><p>BOYACTUAR materializa las necesidades expresadas en la Mesa de Participación de Niños, Niñas y Adolescentes (MPNNA) del departamento de Boyacá, escuchando las voces de los niños, niñas y adolescentes para la construcción de herramientas de prevención y movilización social. La estrategia busca transformar las actividades desde la oferta institucional hacia iniciativas de creación colectiva desde la demanda, en un ejercicio de construcción de ciudadanía y gobernanza con la participación activa de esta población.</p><p><em>Información remitida por el ICBF – Regional Boyacá (Grupo Interno de Trabajo de Prevención) al Observatorio de Asuntos de Género, mayo de 2026.</em></p>', 'ICBF – Regional Boyacá', 'uploads/cms/2026/06/banner-genero.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='icbf-una-hora-por-la-prevencion');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'ICBF: «Padres en tu Trabajo», 87 encuentros y 3.653 participantes en empresas del departamento', 'icbf-padres-en-tu-trabajo', 'La estrategia BOYACTUAR entiende las realidades alrededor de los fenómenos de violencia y examina con atención las cifras que evidencian un alto porcentaje de casos provenientes del interior de los hogares. Sin embargo, reconoce también la necesidad de establecer un enfoque de…', '<p>La estrategia BOYACTUAR entiende las realidades alrededor de los fenómenos de violencia y examina con atención las cifras que evidencian un alto porcentaje de casos provenientes del interior de los hogares. Sin embargo, reconoce también la necesidad de establecer un enfoque de generatividad para abordar los recursos resolutivos con los que cuentan las familias y las interacciones saludables que se generan en su interior, trabajando en su fortalecimiento desde una connotación positiva que se traduce en una mirada de esperanza. En este sentido, se reconoce que fenómenos de marginalidad y exclusión social golpean a las familias, por lo que se requiere un manto de cobertura institucional empático y sintonizado con sus realidades, capaz de prevenir factores de riesgo y consolidarlas como el gran y primer entorno protector.</p><p>BOYACTUAR utiliza estrategias y espacios convencionales, redefinidos y motivados en un formato de trabajo departamental desde el sentir de la institucionalidad y las comunidades, movilizadas hacia el cambio. Se trata de encuentros con padres y familias resignificados desde sus realidades e impulsados hacia un mejor vivir, con incidencia directa en el desarrollo socioafectivo de los niños, niñas y adolescentes. Las familias participantes no asisten a una citación más de colegio, sino que se convierten en parte activa de la estrategia, en coherencia con las acciones del plan de desarrollo departamental.</p><p>En este marco se realizaron 87 encuentros en diferentes empresas del departamento, logrando atender a un total de 3653 participantes. Estos espacios, denominados Encuentros de formación “Padres en tu trabajo”, se enfocaron en el fortalecimiento de pautas de crianza en el entorno laboral, acercando la prevención y la promoción de entornos protectores a los lugares donde las familias desarrollan su vida cotidiana.</p><p>De esta manera, BOYACTUAR avanza en la construcción de una estrategia integral que no solo atiende las problemáticas de violencia, sino que también potencia las capacidades de las familias y su rol como primer entorno protector, generando un impacto positivo en la vida de los niños, niñas y adolescentes del departamento.</p><p><em>Información remitida por el ICBF – Regional Boyacá (Grupo Interno de Trabajo de Prevención) al Observatorio de Asuntos de Género, mayo de 2026.</em></p>', 'ICBF – Regional Boyacá', 'uploads/cms/2026/06/banner-genero.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='icbf-padres-en-tu-trabajo');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'ICBF: Feria del Buen Trato movilizó a 12.708 niños, niñas y adolescentes en 108 municipios', 'icbf-feria-del-buen-trato', 'La actividad denominada Feria del Buen Trato fue liderada por 108 Mesas de Participación de Niños, Niñas y Adolescentes (MPNNA) en el departamento, contando con la participación activa de 12.708 niños, niñas y adolescentes. Esta iniciativa tuvo como propósito dar a conocer la…', '<p>La actividad denominada Feria del Buen Trato fue liderada por 108 Mesas de Participación de Niños, Niñas y Adolescentes (MPNNA) en el departamento, contando con la participación activa de 12.708 niños, niñas y adolescentes. Esta iniciativa tuvo como propósito dar a conocer la oferta institucional disponible en cada territorio, orientada a la prevención de violencias y a la promoción de entornos seguros y protectores.</p><p>La Feria se consolidó como un espacio de encuentro y movilización social y divulgación pedagógica en el que los niños, niñas y adolescentes fueron protagonistas, visibilizando las acciones que desde las instituciones se adelantan para garantizar sus derechos. A través de actividades pedagógicas, lúdicas y de participación, se fortaleció el reconocimiento de la corresponsabilidad entre el Estado, la familia y la sociedad en la construcción de ambientes protectores.</p><p>La estrategia permitió que cada territorio mostrara sus avances y herramientas en materia de prevención, generando un diálogo directo con la niñez y adolescencia, quienes no solo recibieron información, sino que también aportaron sus voces y experiencias para enriquecer la construcción colectiva de soluciones.</p><p><em>Información remitida por el ICBF – Regional Boyacá (Grupo Interno de Trabajo de Prevención) al Observatorio de Asuntos de Género, mayo de 2026.</em></p>', 'ICBF – Regional Boyacá', 'uploads/cms/2026/06/banner-genero.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='icbf-feria-del-buen-trato');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'ICBF: «Llegar Juntos y a Tiempo», articulación contra las violencias en Puerto Boyacá', 'icbf-llegar-juntos-y-a-tiempo-puerto-boyaca', 'La estrategia “Llegar Juntos y a Tiempo” se desarrolló en el municipio de Puerto Boyacá, movilizando al Sistema Nacional de Bienestar Familiar y articulando esfuerzos en el marco de la Mesa de Infancia, Adolescencia y Fortalecimiento Familiar. Este ejercicio permitió dar a…', '<p>La estrategia “Llegar Juntos y a Tiempo” se desarrolló en el municipio de Puerto Boyacá, movilizando al Sistema Nacional de Bienestar Familiar y articulando esfuerzos en el marco de la Mesa de Infancia, Adolescencia y Fortalecimiento Familiar. Este ejercicio permitió dar a conocer una propuesta integral orientada a la prevención de violencias desde diferentes sectores, con la participación activa de la Mesa de Participación de Niños, Niñas y Adolescentes. En este espacio, los niños, niñas y adolescentes identificaron factores de riesgo y generaron alertas que fueron presentadas en el Consejo de Política Social, fortaleciendo así la voz de la niñez y adolescencia en la toma de decisiones públicas.</p><p>La estrategia se desplegó en múltiples escenarios del municipio. Se realizaron recorridos por el sector comercial, donde se socializaron las rutas de atención en caso de violencias, acercando la información directamente a la comunidad y promoviendo la corresponsabilidad ciudadana en la protección de los derechos. Paralelamente, se llevaron a cabo talleres en instituciones educativas, espacios que permitieron sensibilizar a estudiantes y docentes sobre la importancia de construir entornos seguros y protectores.</p><p>Otro componente clave fue la implementación de la estrategia Padres en tu trabajo, que acercó procesos de formación y fortalecimiento de pautas de crianza al entorno laboral, reconociendo que la prevención también debe llegar a los espacios cotidianos de las familias. Asimismo, se desarrollaron actividades de fortalecimiento familiar a través de las mochilas atrapasueños, herramientas pedagógicas que buscan promover el buen trato, la comunicación y la cohesión familiar como pilares fundamentales para la protección de niños, niñas y adolescentes.</p><p>En conjunto, la estrategia “Llegar Juntos y a Tiempo” en Puerto Boyacá representó un ejercicio de articulación institucional y comunitaria, en el que se integraron acciones de prevención, sensibilización y fortalecimiento familiar. Su impacto se reflejó en la movilización de diferentes sectores, en la participación activa de la niñez y adolescencia, y en la consolidación de la familia como primer entorno protector. Con estas acciones, el departamento reafirma su compromiso con la construcción de una sociedad más segura, solidaria y consciente de la importancia de garantizar los derechos de los niños, niñas y adolescentes.</p><p><em>Información remitida por el ICBF – Regional Boyacá (Grupo Interno de Trabajo de Prevención) al Observatorio de Asuntos de Género, mayo de 2026.</em></p>', 'ICBF – Regional Boyacá', 'uploads/cms/2026/06/banner-genero.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='icbf-llegar-juntos-y-a-tiempo-puerto-boyaca');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'ICBF: diálogo intercultural con la comunidad Emberá Katío por los derechos de niñas y mujeres', 'icbf-territorio-embera-puerto-boyaca', 'En el marco de las acciones orientadas a la promoción y garantía de los derechos sexuales y reproductivos, se llevó a cabo un diálogo intercultural entre el Instituto Colombiano de Bienestar Familiar (ICBF) y autoridades indígenas de la comunidad Emberá Katío, concebido como un…', '<p>En el marco de las acciones orientadas a la promoción y garantía de los derechos sexuales y reproductivos, se llevó a cabo un diálogo intercultural entre el Instituto Colombiano de Bienestar Familiar (ICBF) y autoridades indígenas de la comunidad Emberá Katío, concebido como un primer espacio de acercamiento, reconocimiento mutuo y construcción de relaciones de confianza. Este encuentro se desarrolló bajo un enfoque diferencial e intercultural, reconociendo la autonomía y cosmovisión de los pueblos indígenas, así como la importancia de armonizar las prácticas culturales con los estándares de derechos humanos, particularmente en lo relacionado con la protección integral de las niñas, adolescentes y mujeres Emberá.</p><p>El diálogo tuvo como propósito principal generar un intercambio de saberes y reflexiones en torno a prácticas nocivas, específicamente la mutilación genital femenina y las uniones tempranas. Durante el desarrollo del espacio, las autoridades indígenas compartieron sus significados culturales, prácticas tradicionales y dinámicas comunitarias relacionadas con estos temas, mientras que el ICBF presentó el marco normativo nacional e internacional en materia de derechos de la niñez, la adolescencia y los derechos sexuales y reproductivos.</p><p>El ejercicio se caracterizó por un ambiente de respeto, escucha activa y disposición al diálogo horizontal, lo que permitió evidenciar tensiones entre las prácticas culturales y los estándares de protección de derechos, así como también la apertura de las autoridades indígenas para reflexionar sobre posibles afectaciones a la salud física, emocional y al proyecto de vida de las niñas. En este sentido, se identificó una disposición inicial para continuar avanzando en la revisión de dichas prácticas, siempre en el marco del reconocimiento de su identidad cultural y procesos de construcción propios.</p><p>Este encuentro constituye un ejercicio inicial que da apertura a un proceso sostenido de trabajo conjunto orientado a la eliminación progresiva de prácticas nocivas, mediante estrategias concertadas, culturalmente pertinentes y sostenibles en el tiempo. Asimismo, resalta la importancia de fortalecer la articulación interinstitucional y la participación activa de liderazgos comunitarios, especialmente de mujeres, parteras y sabedores ancestrales, como actores clave en la transformación social al interior de la comunidad.</p><p><em>Información remitida por el ICBF – Regional Boyacá (Grupo Interno de Trabajo de Prevención) al Observatorio de Asuntos de Género, mayo de 2026.</em></p>', 'ICBF – Regional Boyacá', 'uploads/cms/2026/06/banner-genero.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='icbf-territorio-embera-puerto-boyaca');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'BOYACTUAR: resultados de la estrategia de prevención de violencias contra niños, niñas y adolescentes', 'icbf-resultados-estrategia-boyactuar', 'La estrategia BOYACTUAR se consolidó en Boyacá como un esfuerzo integral para promover la prevención, detección temprana y atención de las violencias contra niños, niñas y adolescentes, fortaleciendo la participación comunitaria, la sensibilización social y el respeto por sus…', '<p>La estrategia BOYACTUAR se consolidó en Boyacá como un esfuerzo integral para promover la prevención, detección temprana y atención de las violencias contra niños, niñas y adolescentes, fortaleciendo la participación comunitaria, la sensibilización social y el respeto por sus derechos. Se implementó en 37 municipios priorizados bajo criterios como alertas tempranas de la Defensoría del Pueblo, estadísticas de violencia de la Fiscalía y la Policía Nacional, municipios vinculados al Tour Violeta 2025 y procesos administrativos de restablecimiento de derechos del ICBF.</p><p>El despliegue de la estrategia se organizó en cinco componentes: con los niños, niñas y adolescentes se fomentó el autocuidado, las habilidades sociales y la participación activa a través de la Feria del Buen Trato; con las familias se realizaron encuentros de formación, la estrategia Padres en tu trabajo y actividades de fortalecimiento con las mochilas atrapasueños; con la comunidad se consolidaron redes protectoras y se hicieron recorridos por sectores comerciales; con las instituciones se adelantaron procesos de capacitación y fortalecimiento en prevención de violencias; y con los medios y redes se promovió una toma masiva de comunicación y difusión de mensajes de protección.</p><p>Los resultados fueron significativos: se ejecutaron Ferias del Buen Trato en 108 municipios, lideradas por las Mesas de Participación de Niños, Niñas y Adolescentes, con la participación de 12.708 niños, niñas y adolescentes. Se realizaron 87 encuentros de la estrategia Padres en tu trabajo en empresas del departamento, con un total de 3.653 participantes. Se fortalecieron las capacidades de comisarías y defensorías de familia, y se capacitó a instituciones educativas y al Mecanismo Articulador departamental y municipal en rutas de atención. Además, se puso en marcha el programa radial “Boyactuar” en la emisora de la Gobernación y en emisoras comunitarias, ampliando el alcance de la estrategia.</p><p>Un ejemplo destacado fue la implementación de la estrategia Llegar Juntos y a Tiempo en Puerto Boyacá, donde se realizaron talleres en cuatro instituciones educativas con 650 estudiantes, un torneo Golombiao con 230 participantes, escuelas de padres en siete empresas locales, recorridos por 12 hoteles y nueve barrios para socializar rutas de atención, y actividades de fortalecimiento familiar con las mochilas atrapasueños. También participaron 91 unidades de servicios del ICBF con 1.512 beneficiarios, y se logró cobertura en medios locales como Voz Claveriana, La Tribuna y Puerto TV.</p><p>En el contexto departamental, entre 2024 y 2025 se registraron 4.980 denuncias de violencias contra niños, niñas y adolescentes, siendo las más frecuentes la violencia física, psicológica, negligencia y violencia sexual. Estos datos refuerzan la importancia de BOYACTUAR como estrategia de prevención y respuesta.</p><p>En conclusión, BOYACTUAR logró posicionarse como un referente en Boyacá para la prevención de violencias, articulando esfuerzos entre instituciones, familias, comunidades y medios de comunicación. Su impacto se refleja en la amplia cobertura territorial, la participación activa de la niñez y adolescencia y el fortalecimiento de la familia como primer entorno protector, reafirmando el compromiso del departamento con una niñez grande, protegida y escuchada.</p><p><em>Información remitida por el ICBF – Regional Boyacá (Grupo Interno de Trabajo de Prevención) al Observatorio de Asuntos de Género, mayo de 2026.</em></p>', 'ICBF – Regional Boyacá', 'uploads/cms/2026/06/banner-genero.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='icbf-resultados-estrategia-boyactuar');

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), '«Ojo al Dato Violeta»: la UPTC realizó 406 acciones de prevención de violencias basadas en género en 2025', 'ogdh-uptc-ojo-al-dato-violeta-2025', 'El Observatorio de Géneros y Derechos Humanos (OGDH) de la UPTC comparte cuatro píldoras informativas con los principales indicadores «Datos Violeta» de su Boletín #4 (2025).', '<p>El Observatorio de Géneros y Derechos Humanos (OGDH) de la Universidad Pedagógica y Tecnológica de Colombia (UPTC), aliado de la Red de Observatorios de Boyacá, remitió cuatro piezas gráficas con píldoras informativas que resumen los principales indicadores «Datos Violeta» de su Boletín #4 del año 2025.</p><p>Entre los datos destacados, durante 2025 la UPTC realizó <strong>406 acciones de prevención</strong> de violencias basadas en género y discriminaciones en la comunidad universitaria (61 % presenciales, 37 % virtuales y 2 % híbridas).</p><p><img src="uploads/cms/2026/09/ogdh-ojo-al-dato-violeta-fase-0.jpg" alt="Ojo al Dato Violeta – pieza 0 (OGDH UPTC)"></p><p><img src="uploads/cms/2026/09/ogdh-ojo-al-dato-violeta-fase-1.jpg" alt="Ojo al Dato Violeta – pieza 1 (OGDH UPTC)"></p><p><img src="uploads/cms/2026/09/ogdh-ojo-al-dato-violeta-fase-2.jpg" alt="Ojo al Dato Violeta – pieza 2 (OGDH UPTC)"></p><p><img src="uploads/cms/2026/09/ogdh-ojo-al-dato-violeta-fase-3.jpg" alt="Ojo al Dato Violeta – pieza 3 (OGDH UPTC)"></p><p><em>Fuente: Observatorio de Géneros y Derechos Humanos – UPTC (Coordinación OGDH). Piezas remitidas a la Red de Observatorios en junio de 2026 para su difusión.</em></p>', 'Observatorio de Géneros y Derechos Humanos – UPTC', 'uploads/cms/2026/09/ogdh-ojo-al-dato-violeta-fase-0.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='ogdh-uptc-ojo-al-dato-violeta-2025');
